  public Pagelet addPagelet(Pagelet pagelet, String composer) {
    List<Pagelet> c = composers.get(composer);
    int position = (c == null) ? 0 : c.size();
    return addPagelet(pagelet, composer, position);
  }

  /**
   * {@inheritDoc}
